SELECT dept_name AS deptName, NVL(SUM(treatment_count), 0) AS treatmentCount, NVL(SUM(treatment_amount), 0) AS treatmentAmount, NVL(SUM(patient_count), 0) AS patientCount FROM TR_SPEC_TREAT_DTL WHERE stat_date BETWEEN #{startDate} AND #{endDate}
AND dept_name LIKE '%' || #{deptName} || '%'
GROUP BY dept_name ORDER BY treatmentCount DESC
